async function seedHealthFacilities() {
  const databaseUrl = process.env.DATABASE_URL;
  if (!databaseUrl) {
    console.log('DATABASE_URL absente : import des etablissements ignore.');
    return;
  }

  const client = new Client({
    connectionString: databaseUrl,
    ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false,
  });

  await client.connect();

  // Ajoute la colonne specialty si la table existe deja sans elle (deploiement
  // anterieur a son introduction) - le CREATE TABLE IF NOT EXISTS du schema
  // ne modifie pas une table deja existante.
  await client.query('ALTER TABLE osm_health_facilities ADD COLUMN IF NOT EXISTS specialty VARCHAR(255)').catch(() => {});

  const countRes = await client.query('SELECT COUNT(*) FROM osm_health_facilities');
  const existing = parseInt(countRes.rows[0].count, 10);
  const withSpecialty = await client.query("SELECT COUNT(*) FROM osm_health_facilities WHERE specialty IS NOT NULL");
  const existingWithSpecialty = parseInt(withSpecialty.rows[0].count, 10);

  if (existing >= FACILITIES.length && existingWithSpecialty > 0) {
    console.log(`La table osm_health_facilities contient deja ${existing} etablissements (dont ${existingWithSpecialty} avec specialite).`);
    await client.end();
    return;
  }

  console.log(`Import/mise a jour de ${FACILITIES.length} etablissements de sante...`);
  let inserted = 0;
  for (const [osmId, category, name, nameAr, addrCity, wilayaId, lat, lng, specialty] of FACILITIES) {
    try {
      await client.query(
        `INSERT INTO osm_health_facilities (osm_id, category, name, name_ar, addr_city, wilaya_id, latitude, longitude, specialty)
         VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9)
         ON CONFLICT (osm_id) DO UPDATE SET specialty = EXCLUDED.specialty`,
        [osmId, category, name, nameAr, addrCity, wilayaId, lat, lng, specialty],
      );
      inserted++;
    } catch (err) {
      // une erreur isolee ne doit pas interrompre l'import du reste
    }
  }
  console.log(`Import termine : ${inserted} etablissements traites.`);
  await client.end();
}

seedHealthFacilities();
